import { createRootRoute, HeadContent, Outlet, Scripts } from "@tanstack/react-router";
import { AuthProvider } from "@/lib/auth/provider";
import { PreviewHostBridge } from "@/components/preview-host-bridge";
import appCss from "../styles.css?url";

const APP_NAME = "Quiet Zone";
// "/" normally, "/QR_Generator/" in the static GitHub Pages build.
const BASE = import.meta.env.BASE_URL;
// The manifest is generated by the Nitro server, which the static build skips.
const STATIC_PAGES = import.meta.env.VITE_STATIC_PAGES === "1";

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: APP_NAME },
      {
        name: "description",
        content: "Make a QR code as you type. Set colors, size, and error correction, then download a PNG.",
      },
      { name: "theme-color", content: "#e7e1d6" },
    ],
    links: [
      { rel: "icon", type: "image/svg+xml", href: `${BASE}favicon.svg` },
      { rel: "preconnect", href: "https://fonts.googleapis.com" },
      { rel: "preconnect", href: "https://fonts.gstatic.com", crossOrigin: "anonymous" },
      {
        rel: "stylesheet",
        href: "https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,560;9..144,650&display=swap",
      },
      { rel: "stylesheet", href: appCss },
      ...(STATIC_PAGES ? [] : [{ rel: "manifest", href: "/__studio/manifest.webmanifest" }]),
      { rel: "apple-touch-icon", href: `${BASE}__studio/icon-180.png` },
    ],
  }),
  component: () => (
    <html lang="en" className="antialiased" suppressHydrationWarning>
      <head>
        <HeadContent />
      </head>
      <body className="min-h-screen bg-bg text-ink">
        <PreviewHostBridge />
        <AuthProvider>
          <Outlet />
        </AuthProvider>
        <Scripts />
      </body>
    </html>
  ),
});
